    @Test void exactAssignmentsCoverEveryIdentity(){assertEquals(new HashSet<>(ThreadArt.IDS),ThreadArt.EXPECTED_ASPECTS.keySet());var retained=Map.ofEntries(Map.entry("stone_makes_promises",ThreadAspect.WORK),Map.entry("world_remembers",ThreadAspect.CONTROL),Map.entry("deep_own_light",ThreadAspect.ROBUSTNESS),Map.entry("silence_has_teeth",ThreadAspect.ENDURANCE),Map.entry("feast_before_journey",ThreadAspect.ENDURANCE),Map.entry("materials_temperaments",ThreadAspect.ROBUSTNESS),Map.entry("pressure_changes_matter",ThreadAspect.IMPACT),Map.entry("rails_turn_distance",ThreadAspect.TEMPO),Map.entry("leave_atmosphere",ThreadAspect.ENDURANCE),Map.entry("blood_infrastructure",ThreadAspect.RENEWAL),Map.entry("army_walks_toward_you",ThreadAspect.IMPACT));retained.forEach((id,aspect)->assertEquals(aspect,ThreadArt.EXPECTED_ASPECTS.get(id),id));assertEquals(ThreadAspect.CONTROL,ThreadArt.EXPECTED_ASPECTS.get("sleep_is_not_an_anchor"));assertEquals(ThreadAspect.TEMPO,ThreadArt.EXPECTED_ASPECTS.get("the_body_learns_new_motions"));}
    @Test void definitionsRequireTeachingOwnershipAndRoutes(){var json=JsonParser.parseString("{\"id\":\"test\",\"concept_id\":\"test.rule\",\"owner\":\"test-producer\",\"title\":\"Test\",\"suit\":\"world\",\"order\":1,\"aspect\":\"control\",\"art\":\"better_content_threads:textures/gui/threads/test.png\",\"rule\":\"This deliberately plain teaching rule contains enough words to satisfy the concise learning contract for every active card in the catalogue.\",\"prose\":\"Prose\",\"invitation\":\"Invitation\",\"action\":\"Do it.\",\"reveal_routes\":[{\"id\":\"r\",\"label\":\"Reveal\",\"type\":\"event\",\"value\":\"a\",\"producer\":\"test-producer\",\"correlation\":\"episode\"}],\"completion_routes\":[{\"id\":\"c\",\"label\":\"Complete\",\"type\":\"event\",\"value\":\"b\",\"producer\":\"test-producer\",\"correlation\":\"episode\"}]}").getAsJsonObject();var definition=ThreadDefinition.parse(json);assertEquals("test.rule",definition.conceptId());assertNull(definition.doorway());json.remove("completion_routes");assertThrows(IllegalArgumentException.class,()->ThreadDefinition.parse(json));}
    @Test void catalogueHasNoFtbDoorwaysAndUsesExactNativeReplacements()throws Exception{var catalogue=JsonParser.parseString(Files.readString(Path.of("src/main/resources/data/better_content_threads/threads/catalogue.json"))).getAsJsonObject().getAsJsonArray("threads");var doorways=new HashMap<String,String>();for(var element:catalogue){var json=element.getAsJsonObject();if(!json.has("doorway")||json.get("doorway").isJsonNull())continue;var doorway=json.getAsJsonObject("doorway");assertNotEquals("ftb",doorway.get("type").getAsString());doorways.put(json.get("id").getAsString(),doorway.get("type").getAsString()+":"+doorway.get("target").getAsString());}assertEquals("font:minecraft:the_nether",doorways.get("fire_has_country"));assertEquals("font:aether:the_aether",doorways.get("sky_another_country"));assertEquals("font:the_bumblezone:the_bumblezone",doorways.get("deep_own_light"));assertEquals("font:rats:ratlantis",doorways.get("silence_has_teeth"));assertEquals("ponder:create:hand_crank",doorways.get("motion_becomes_industry"));assertEquals("ponder:create:large_water_wheel",doorways.get("rivers_turn_work"));assertEquals("emi:create:precision_mechanism",doorways.get("precision_has_rhythm"));assertEquals("emi:powergrid:generator_housing",doorways.get("electricity_agreement"));assertEquals("ponder:create:track_station",doorways.get("rails_turn_distance"));assertEquals("emi:vs_eureka:oak_ship_helm",doorways.get("vessel_becomes_place"));assertEquals("emi:creatingspace:rocket_controls",doorways.get("leave_atmosphere"));assertFalse(doorways.containsKey("ruins_are_instructions"));}
    @Test void everyRouteHasExactProducerAndCorrelationCoverage()throws Exception{var catalogue=JsonParser.parseString(Files.readString(Path.of("src/main/resources/data/better_content_threads/threads/catalogue.json"))).getAsJsonObject().getAsJsonArray("threads");int routes=0;var keys=new HashSet<String>();for(var element:catalogue){var definition=ThreadDefinition.parse(element.getAsJsonObject());for(var route:java.util.stream.Stream.concat(definition.revealRoutes().stream(),definition.completionRoutes().stream()).toList()){routes++;assertFalse(route.producer().isBlank());assertEquals("episode",route.correlation());assertTrue(keys.add(definition.id()+":"+route.id()));}}assertEquals(108,routes);assertEquals(108,keys.size());}
