    @Test void runtimeArtUsesOnlyUntouchedImagesAndThumbnails()throws Exception{Path root=Path.of("src/main/resources/assets/better_content_threads/textures/gui/threads");try(var files=Files.list(root)){var names=files.filter(Files::isRegularFile).map(path->path.getFileName().toString()).toList();assertEquals(104,names.size());assertFalse(names.stream().anyMatch(name->name.endsWith("_archive.png")||name.endsWith("_pigment.png")||name.endsWith("_aspect.png")));}for(String id:ThreadArt.IDS){for(String suffix:List.of(".png","_thumb.png")){var image=ImageIO.read(root.resolve(id+suffix).toFile());assertNotNull(image,id+suffix);assertEquals(256,image.getWidth(),id+suffix);assertEquals(384,image.getHeight(),id+suffix);}}}
    @Test void retainedArtContainsNoLegacyExactTracePixels()throws Exception{var legacy=Map.of(ThreadAspect.IMPACT,0xE4717D,ThreadAspect.TEMPO,0xAA652B,ThreadAspect.WORK,0xCAA903,ThreadAspect.MOBILITY,0xC0E304,ThreadAspect.ENDURANCE,0x35BBD0,ThreadAspect.ROBUSTNESS,0x1175FC,ThreadAspect.RENEWAL,0x6FEDBA,ThreadAspect.CONTROL,0x8A6CB2);var replacements=Set.of("sleep_is_not_an_anchor","hunger_is_not_nutrition","food_carries_weather","coins_do_not_climb","the_end_is_not_a_door","recipes_obey_this_world","the_body_learns_new_motions");Path root=Path.of("src/main/resources/assets/better_content_threads/textures/gui/threads");for(var entry:ThreadArt.ENTRIES){if(replacements.contains(entry.id()))continue;for(String suffix:List.of(".png","_thumb.png")){var image=ImageIO.read(root.resolve(entry.id()+suffix).toFile());for(int y=0;y<image.getHeight();y++)for(int x=0;x<image.getWidth();x++)assertNotEquals(legacy.get(entry.aspect()).intValue(),image.getRGB(x,y)&0xFFFFFF,entry.id()+suffix);}}}
