    @Test void completionHistoryIsMonotonicAndRouteAware(){var root=new CompoundTag();root.putInt("schema",4);var known=new ListTag();known.add(StringTag.valueOf("world_remembers"));root.put("known",known);var active=new ListTag();active.add(StringTag.valueOf("world_remembers"));root.put("active",active);var state=ThreadPlayerState.fromTag(root);assertTrue(state.complete("world_remembers","Returned trace",3));assertFalse(state.complete("world_remembers","Returned trace",3));assertEquals(1,state.completionCounts.get("world_remembers"));assertEquals("Returned trace ×1",state.routeSummary("world_remembers"));}
