    @Test void loadingBriefSessionWrapsManuallyAndRequiresExplicitCarryOver(){var briefs=List.of(LoadingBriefs.FALLBACK,new LoadingBrief("second","learning.second","test-owner","","Practice","Second lesson","This deliberately concise loading lesson contains enough plain words to satisfy the required communication contract while explaining a useful changed rule without revealing progression spoilers.","Practice this rule before danger arrives.",new net.minecraft.resources.ResourceLocation("minecraft","textures/item/book.png")));var session=new LoadingBriefSession(briefs,new LoadingBriefRotation.State(Set.of(),""));assertFalse(session.keepReading());assertTrue(session.toggleKeepReading());assertEquals("second",session.move(-1).id());assertEquals("threads",session.move(1).id());assertEquals(List.of("threads","second"),session.viewed());}
