    @Test void loadingBriefManifestHasSixteenOwnedLinkedLessonsWithWideArt()throws Exception{var root=JsonParser.parseString(Files.readString(Path.of("src/main/resources/assets/better_content_threads/loading_briefs/catalogue.json"))).getAsJsonObject();assertEquals("bc.loading_briefs.v3",root.get("schema").getAsString());var briefs=root.getAsJsonArray("briefs");assertEquals(16,briefs.size());assertEquals(List.of("threads","hud","water","nutrition","variety","metabolism","temperature","movement","sleep","downing","life","seasons","weather","pollution","physics","campaigns"),java.util.stream.StreamSupport.stream(briefs.spliterator(),false).map(element->element.getAsJsonObject().get("id").getAsString()).toList());var threads=JsonParser.parseString(Files.readString(Path.of("src/main/resources/data/better_content_threads/threads/catalogue.json"))).getAsJsonObject().getAsJsonArray("threads");var concepts=new HashMap<String,String>();for(var element:threads){var row=element.getAsJsonObject();concepts.put(row.get("id").getAsString(),row.get("concept_id").getAsString());}for(var element:briefs){var brief=LoadingBrief.parse(element.getAsJsonObject());assertFalse(brief.owner().isBlank(),brief.id());if(!brief.relatedThread().isEmpty())assertEquals(brief.conceptId(),concepts.get(brief.relatedThread()),brief.id());var path=Path.of("src/main/resources/assets/better_content_threads",brief.art().getPath());var image=ImageIO.read(path.toFile());assertNotNull(image,brief.id());assertEquals(512,image.getWidth(),brief.id());assertEquals(256,image.getHeight(),brief.id());}String movement=briefs.get(7).getAsJsonObject().get("body").getAsString();assertTrue(movement.contains("directional double-tap dodging is disabled"));assertFalse(movement.contains("double taps also dodge"));}
